ES256-GCM-SHA384; 20 ssl_prefer_server_ciphers off; 21 ssl_session_cache shared:SSL:10m; 22 ssl_session_timeout 1d; 23 ssl_session_tickets off; 24 ssl_certificate &#34;/data/tpinellia.com/fullchain.crt&#34;; 25 ssl_certificate_key &#34;/data/tpinellia.com/privkey.key&#34;; # 改成你的证书地址 26 27 access_log /var/log/nginx/xxxx.access.log; 28 error_log /var/log/nginx/xxx.error.log; 29 30	location /awesomepath { # 与 V2Ray 配置中的 path 保持一致 31 proxy_redirect off; 32 proxy_pass http://127.0.0.1:12345; # 假设v2ray的监听地址是12345 33 proxy_http_version 1.1; 34 proxy_set_header Upgrade $http_upgrade; 35 proxy_set_header Connection &#34;upgrade&#34;; 36 proxy_set_header Host $host; 37 proxy_set_header X-Real-IP $remote_addr; 38 proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for; 39 } 40} server { listen 80; listen [::]:80; listen 443 ssl; listen [::]:443 ssl; server_name tpinellia.com; ssl_certificate &quot;/data/tpinellia.com/fullchain.pem&quot;; ssl_certificate_key &quot;/data/tpinellia.com/privkey.pem&quot;; return 301 https://www.tpinellia.com$request_uri; }
